import{_ as o}from"./chunks/02.7bSgNsEh.js";import{_ as n,o as s,c as r,j as t,a,aa as v}from"./chunks/framework.BAs_AphD.js";const i="/buildary-help-preview/academy/img/zalozeni-stavby/02.webp",l="/buildary-help-preview/academy/img/zalozeni-stavby/09.webp",d="/buildary-help-preview/media/cs/diary/kopirovani_stavby.png",g=JSON.parse('{"title":"Založit stavbu","description":"","frontmatter":{"title":"Založit stavbu","wiki":"cs:diary:projectsetup"},"headers":[],"relativePath":"diary/projectsetup.md","filePath":"diary/projectsetup.md","lastUpdated":1794209661000}'),u={name:"diary/projectsetup.md"};function b(p,e,m,y,k,z){return s(),r("div",null,[...e[0]||(e[0]=[t("h1",{id:"zalozit-stavbu",tabindex:"-1"},[a("Založit stavbu "),t("a",{class:"header-anchor",href:"#zalozit-stavbu","aria-label":'Permalink to "Založit stavbu"'},"​")],-1),t("p",null,[a("Stavba zastřešuje všechno ostatní: projektový tým, deníky, úkoly i soupisy prací. Založíte ji v Seznamu staveb tlačítkem "),t("strong",null,"Nová stavba"),a(", novou stavbu můžete také zkopírovat z existující nebo založit podle vzorové stavby.")],-1),t("p",null,[a("Krok za krokem: "),t("a",{href:"/buildary-help-preview/akademie/zalozeni-stavby"},"Založit novou stavbu"),a(" v Akademii.")],-1),t("div",{class:"video"},[t("iframe",{src:"https://www.youtube-nocookie.com/embed/_RrM5TPoGDM",title:"Video: Založení stavby",loading:"lazy",allowfullscreen:"",allow:"accelerometer; encrypted-media; gyroscope; picture-in-picture"})],-1),v('<h2 id="kdo-muze-stavbu-zalozit" tabindex="-1">Kdo může stavbu založit <a class="header-anchor" href="#kdo-muze-stavbu-zalozit" aria-label="Permalink to &quot;Kdo může stavbu založit&quot;">​</a></h2><ul><li>V <strong>osobní doméně</strong> máte všechna práva automaticky.</li><li>Ve <strong>firemní doméně</strong> potřebujete právo <strong>Založení stavby</strong>. Pokud ho nemáte, požádejte administrátora domény, aby vám ho přidělil, nebo aby stavbu založil sám. Viz <a href="/buildary-help-preview/diary/userpermissions">Kdo co smí v deníku</a>.</li><li>Dokud má doména neuhrazené faktury, novou stavbu v ní nezaložíte – viz <a href="/buildary-help-preview/firstofall/payment#splatnost-a-neuhrazene-faktury">Splatnost a neuhrazené faktury</a>.</li></ul><h2 id="zalozit-stavbu-1" tabindex="-1">Založit stavbu <a class="header-anchor" href="#zalozit-stavbu-1" aria-label="Permalink to &quot;Založit stavbu&quot;">​</a></h2><p>V levém panelu otevřete <strong>Seznam staveb</strong>, klikněte na <strong>Nová stavba</strong>, vyplňte formulář a klikněte na <strong>Uložit</strong>. Pak se otevře Seznam deníků stavby – pokračujte <a href="/buildary-help-preview/diary/diarysetup">založením deníku</a>.</p><figure class="shot" style="--w:760px;"><img src="'+i+'" alt="Formulář Nová stavba s poli Název stavby, Doména, Jazyk a Zahájení stavby dle SOD" loading="lazy"></figure><h3 id="udaje-o-stavbe" tabindex="-1">Údaje o stavbě <a class="header-anchor" href="#udaje-o-stavbe" aria-label="Permalink to &quot;Údaje o stavbě&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pole</th><th>Co do něj patří</th></tr></thead><tbody><tr><td><strong>Obrázek stavby</strong></td><td>Charakteristický obrázek, podle kterého stavbu poznáte v Seznamu staveb. Doporučená velikost je 320 × 320 pixelů, jiné rozměry se přizpůsobí.</td></tr><tr><td><strong>Název stavby</strong></td><td>Plný název stavby podle stavebního povolení.</td></tr><tr><td><strong>Zkrácený název stavby</strong></td><td>Používá se tam, kde je plný název moc dlouhý – v mobilu, v přehledech a v názvech souborů PDF.</td></tr><tr><td><strong>Číslo objednávky</strong>, <strong>Číslo stavby dle zhotovitele</strong>, <strong>Číslo stavby dle stavebníka</strong></td><td>Nepovinné označení stavby. Číslo stavby dle stavebníka se zobrazuje i v levém panelu pod názvem stavby.</td></tr><tr><td><strong>Doména</strong></td><td>Doména (firma), pod kterou bude stavba vedena a fakturována.</td></tr><tr><td><strong>Jazyk</strong></td><td>Jazyk stavby: v něm se vytvoří číselníky a názvy sekcí deníku.</td></tr><tr><td><strong>Použít vzorovou stavbu</strong></td><td>Vzorová stavba, ze které se převezme nastavení – viz <a href="#vzorova-stavba">Vzorová stavba</a>.</td></tr><tr><td><strong>Zahájení stavby dle SOD</strong>, <strong>Ukončení stavby dle SOD</strong></td><td>Smluvní termíny podle smlouvy o dílo.</td></tr><tr><td><strong>Měna</strong></td><td>Měna stavby.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Doménu a jazyk zvolte pečlivě</p><p>Po založení stavby doménu ani jazyk nezměníte. Pokud potřebujete stavbu v jiném jazyce, přepište číselníky ručně, nebo založte novou stavbu.</p></div><h3 id="umisteni" tabindex="-1">Umístění <a class="header-anchor" href="#umisteni" aria-label="Permalink to &quot;Umístění&quot;">​</a></h3><p>Do pole <strong>Místo stavby</strong> začněte psát adresu a vyberte ji z nabídky. Buildary doplní <strong>zeměpisnou šířku a délku</strong> a ukáže místo na mapě. Polohu můžete upřesnit i kliknutím do mapy.</p><p>Podle souřadnic se do deníku automaticky načítá <strong>počasí</strong>. Bez nich počasí automaticky načíst nejde, proto adresu vždy vybírejte z nabídky.</p><p><strong>Časová zóna stavby</strong> – pro stavby v Česku a na Slovensku ponechte výchozí. Stavíte-li jinde, zvolte správnou zónu; i ta je potřeba pro načítání počasí.</p><figure class="shot" style="--w:760px;"><img src="'+l+'" alt="Umístění stavby na mapě, Používané moduly, Stavba s jedním deníkem a Vytvořit vzorovou stavbu" loading="lazy"></figure><h3 id="pouzivane-moduly" tabindex="-1">Používané moduly <a class="header-anchor" href="#pouzivane-moduly" aria-label="Permalink to &quot;Používané moduly&quot;">​</a></h3><p>Zaškrtněte moduly, které budete na stavbě používat: <strong>Modul Elektronický stavební deník</strong>, <strong>Modul Management úkolů</strong> a <strong>Modul Soupisy provedených prací</strong>. Výchozí výběr stavba přebírá z nastavení domény. Aspoň jeden modul musí zůstat zapnutý. V levém panelu se zobrazují jen moduly zapnuté na otevřené stavbě.</p><ul><li>Moduly ovlivňují <strong>cenu</strong> za stavbu – viz <a href="/buildary-help-preview/firstofall/payment">Placený režim a fakturace</a>.</li><li>Moduly můžete kdykoli změnit v Nastavení stavby. Do data změny se fakturuje podle původního nastavení, od něj podle nového. Proto moduly nejde měnit vícekrát za den.</li><li>Na stavbách v doméně s <strong>individuálním režimem</strong> moduly měnit nemůžete – jsou dané nastavením domény.</li></ul><h3 id="stavba-s-jednim-denikem" tabindex="-1">Stavba s jedním deníkem <a class="header-anchor" href="#stavba-s-jednim-denikem" aria-label="Permalink to &quot;Stavba s jedním deníkem&quot;">​</a></h3><p>Volba je ve výchozím stavu zaškrtnutá. Hodí se, když na stavbě povedete jediný deník: každý nový člen projektového týmu se do deníku automaticky přidá jako oprávněná osoba.</p><p>Počítáte-li s více deníky (objektové, podzhotovitelské a podobně), volbu zrušte. Členy týmu pak do jednotlivých deníků přidáváte sami – viz <a href="/buildary-help-preview/diary/projectteam">Projektový tým: firmy a lidé</a>.</p><h3 id="vytvorit-vzorovou-stavbu" tabindex="-1">Vytvořit vzorovou stavbu <a class="header-anchor" href="#vytvorit-vzorovou-stavbu" aria-label="Permalink to &quot;Vytvořit vzorovou stavbu&quot;">​</a></h3><p>Tuto volbu vidí jen administrátor domény. Označí jí stavbu jako vzorovou – viz <a href="#vzorova-stavba">Vzorová stavba</a>.</p><h2 id="nastaveni-stavby" tabindex="-1">Nastavení stavby <a class="header-anchor" href="#nastaveni-stavby" aria-label="Permalink to &quot;Nastavení stavby&quot;">​</a></h2><p>Údaje o stavbě i všechno další nastavení najdete v <strong>Nastavení stavby</strong>. Otevřete ho:</p><ul><li>v Seznamu staveb ikonou tužky na řádku stavby, nebo</li><li>v levém panelu otevřené stavby kliknutím na obrázek stavby, na její název nebo na ikonu ozubeného kola.</li></ul><table tabindex="0"><thead><tr><th>Záložka</th><th>Co v ní nastavíte</th></tr></thead><tbody><tr><td><strong>Stavba</strong></td><td>Údaje z formuláře výše. Vpravo nahoře je stav stavby, tlačítko <strong>Ukončit stavbu</strong> a menu se třemi tečkami s volbou <strong>Nová stavba kopírováním</strong>.</td></tr><tr><td><strong>Projektový tým</strong></td><td>Firmy a lidé na stavbě a jejich role – viz <a href="/buildary-help-preview/diary/projectteam">Projektový tým: firmy a lidé</a>.</td></tr><tr><td><strong>Části stavby a výkresy</strong></td><td>Rozdělení stavby a výkresy pro umisťování záznamů a úkolů – viz <a href="/buildary-help-preview/diary/projectparts">Části stavby a výkresy</a>.</td></tr><tr><td><strong>Číselníky - Stavební deník</strong></td><td>Kategorie Dalších záznamů a nabídky osob, mechanizmů a materiálů – viz <a href="/buildary-help-preview/diary/codelists">Číselníky deníku</a>.</td></tr><tr><td><strong>Číselníky - Management úkolů</strong></td><td>Kategorie úkolů, štítky a pravidla pro Řešitele a Schvalovatele – viz <a href="/buildary-help-preview/tickets/rules">Kategorie, štítky a pravidla</a>.</td></tr></tbody></table><p>Nastavení stavby smíte měnit, jen když k tomu máte oprávnění – na stavbě kompetenci <strong>Administrace stavby</strong>, nebo odpovídající právo v doméně. Viz <a href="/buildary-help-preview/diary/userpermissions">Kdo co smí v deníku</a>.</p><figure class="shot" style="--w:760px;"><img src="'+o+'" alt="Nastavení stavby, záložka Stavba s tlačítkem Ukončit stavbu" loading="lazy"></figure><h3 id="co-nastavit-po-zalozeni" tabindex="-1">Co nastavit po založení <a class="header-anchor" href="#co-nastavit-po-zalozeni" aria-label="Permalink to &quot;Co nastavit po založení&quot;">​</a></h3><ol><li>Přidejte firmy a lidi do <a href="/buildary-help-preview/diary/projectteam">projektového týmu</a>.</li><li>Pokud budete záznamy nebo úkoly umisťovat do výkresů, rozdělte stavbu na <a href="/buildary-help-preview/diary/projectparts">části a nahrajte výkresy</a>.</li><li>Volitelně připravte <a href="/buildary-help-preview/diary/codelists">číselníky deníku</a>.</li><li><a href="/buildary-help-preview/diary/diarysetup">Založte deník</a>.</li></ol><h2 id="nova-stavba-kopirovanim" tabindex="-1">Nová stavba kopírováním <a class="header-anchor" href="#nova-stavba-kopirovanim" aria-label="Permalink to &quot;Nová stavba kopírováním&quot;">​</a></h2><p>Zakládáte-li stavbu podobnou té, kterou už v doméně máte, zkopírujte ji. V Nastavení stavby, kterou chcete zkopírovat, otevřete menu se třemi tečkami, zvolte <strong>Nová stavba kopírováním</strong> a zadejte název nové stavby.</p><figure class="shot" style="--w:640px;"><img src="'+d+'" alt="Menu se třemi tečkami v Nastavení stavby s volbou Nová stavba kopírováním" loading="lazy"></figure><p>Nová stavba převezme z původní:</p><ul><li>informace o stavbě,</li><li>projektový tým,</li><li>Číselníky - Stavební deník,</li><li>Číselníky - Management úkolů.</li></ul><h2 id="vzorova-stavba" tabindex="-1">Vzorová stavba <a class="header-anchor" href="#vzorova-stavba" aria-label="Permalink to &quot;Vzorová stavba&quot;">​</a></h2><p>Vzorová stavba se hodí firmám s více stavbami, kterým nevyhovuje výchozí nastavení. Administrátor domény připraví nastavení jednou ve vzorové stavbě a při zakládání dalších staveb ho jen převezme. Nastavení ze vzorové stavby má přednost před výchozími číselníky a nastavením.</p><p>Ve vzorové stavbě můžete přednastavit:</p><ul><li>používané moduly a volbu <strong>Stavba s jedním deníkem</strong>,</li><li>projektový tým,</li><li>Číselníky - Stavební deník,</li><li>Číselníky - Management úkolů.</li></ul><p><strong>Vytvořit vzorovou stavbu:</strong> administrátor domény založí stavbu se zaškrtnutou volbou <strong>Vytvořit vzorovou stavbu</strong> a pak ji nastaví. Vzorových staveb může mít doména i několik.</p><p><strong>Použít vzorovou stavbu:</strong> při zakládání nové stavby po výběru domény vyberte v poli <strong>Použít vzorovou stavbu</strong> příslušnou vzorovou stavbu.</p><table tabindex="0"><thead><tr><th></th><th>Nová stavba kopírováním</th><th>Vzorová stavba</th></tr></thead><tbody><tr><td>Odkud se nastavení bere</td><td>Z běžné stavby, kterou kopírujete</td><td>Ze vzorové stavby, kterou připravil administrátor domény</td></tr><tr><td>Co se převezme</td><td>Informace o stavbě, projektový tým, oba číselníky</td><td>Moduly, volba Stavba s jedním deníkem, projektový tým, oba číselníky</td></tr><tr><td>Kdy se hodí</td><td>Jednorázově, když je nová stavba podobná existující</td><td>Opakovaně, když chcete mít všechny stavby nastavené stejně</td></tr></tbody></table>',41)])])}const j=n(u,[["render",b]]);export{g as __pageData,j as default};
